import openpyxl

path='/root/output/rar_result.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
ws=wb['Gold price']

# determine last row with price in column B (numeric)
last=None
for r in range(2, ws.max_row+1):
    v=ws.cell(r,2).value
    if isinstance(v,(int,float)):
        last=r

if last is None:
    raise RuntimeError('No prices found')

# Clear existing vol formulas
for r in range(2, last+1):
    ws.cell(r,4).value=None
    ws.cell(r,5).value=None

# 3M vol starts when we have 3 returns: return starts at row 3, so first 3 returns end at row 5
for r in range(5, last+1):
    ws.cell(r,4).value = f"=IF(C{r}='', '', STDEV.P(C{r-2}:C{r}))"

# 12M vol (annualized) starts when we have 12 returns: return starts at row 3, so 12th return is row 14
for r in range(14, last+1):
    ws.cell(r,5).value = f"=IF(C{r}='', '', STDEV.P(C{r-11}:C{r})*SQRT(12))"

# Ensure Excel recalculates on open
try:
    wb.calculation.calcMode='auto'
    wb.calculation.fullCalcOnLoad=True
except Exception:
    pass

wb.save(path)
print('Updated formulas up to row',last)
# Show a few rows for sanity
for r in range(2, last+1):
    if r<=6 or r>=last-1:
        print(r, ws.cell(r,1).value, ws.cell(r,3).value, ws.cell(r,4).value, ws.cell(r,5).value)
