{"summary":"Search workbook for existing formulas to match style","command":"python3 - <<'PY'
import openpyxl, re
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
formulas=[]
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v,str) and v.startswith('='):
                formulas.append(v)
print('formula_count',len(formulas))
if formulas:
    # show unique function tokens
    funcs=set()
    for f in formulas:
        # simple regex capture function names before (
        for m in re.finditer(r'([A-Z][A-Z0-9\._]*)\(', f.upper()):
            funcs.add(m.group(1))
    print('functions',sorted(funcs)[:50])
    print('sample formulas',formulas[:10])
